import {validateBuildPlan} from './engine/build-plan.mjs';
import {resolveWheelMainstat} from './engine/wheel-stats.mjs';
import {searchWheelCatalog} from './engine/wheel-search.mjs';
import {resolveClientBuildPrimary,resolveClientAdvancementPrimary} from './engine/client-build-stats.mjs';
import {assembleKnownBuildComponents} from './engine/build-component-assembly.mjs';
import {assessInstalledWheelIdentity} from './engine/wheel-current-compatibility.mjs';
const $=id=>document.getElementById(id);let catalog,wheelMechanics,wheelCurrentCompatibility,clientDataByBuild={},clientBuild,team=[],nextId=1;
const selectedClientData=()=>clientDataByBuild[clientBuild]??null;
function invalidate(){$('plan-status').textContent='Plan changed. Export to update the saved JSON.';$('error').textContent='';}
function select(rows,value,onChange,label){const s=document.createElement('select'),empty=document.createElement('option');empty.value='';empty.textContent=label;s.append(empty);for(const row of rows){const o=document.createElement('option');o.value=row.id;o.textContent=`${row.name} · ${row.realm}`;s.append(o);}s.value=value??'';s.addEventListener('change',()=>{onChange(s.value||null);invalidate();});return s;}
function labelled(text,input,id){const label=document.createElement('label');label.htmlFor=id;label.textContent=text;input.id=id;return [label,input];}
function renderWheelSlot(member,wheelSlot,index){
  const wrap=document.createElement('div'),heading=document.createElement('h3'),filter=document.createElement('input'),filterLabel=document.createElement('label'),picker=document.createElement('select'),pickerLabel=document.createElement('label'),prefix=`${member.slotId}-${wheelSlot.slotId}`;
  wrap.className='wheel-picker';heading.textContent=`Wheel slot ${index+1}`;filter.id=prefix+'-filter';filter.type='search';filter.placeholder='Name, owner, main stat or mechanic tag';filterLabel.htmlFor=filter.id;filterLabel.textContent=`Filter Wheel slot ${index+1}`;
  picker.id=prefix+'-wheel';pickerLabel.htmlFor=picker.id;pickerLabel.textContent=`Wheel ${index+1}`;
  const fill=()=>{const selected=wheelSlot.wheelId,result=searchWheelCatalog({catalogRevision:catalog.source.revision,query:filter.value,characterId:member.characterId,ownerMatchOnly:false,tags:[],realms:[],mainstatKeys:[],limit:catalog.wheels.length},catalog),rows=[...result.results];if(selected&&!rows.some(row=>row.id===selected))rows.push(catalog.wheels.find(row=>row.id===selected));picker.replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='Empty / unspecified';picker.append(empty);for(const wheel of rows){const option=document.createElement('option');option.value=wheel.id;const ownerMatch=member.characterId!==null&&wheel.ownerAwakenerId===member.characterId?' · owner match':'',owner=wheel.ownerAwakenerName?` · ${wheel.ownerAwakenerName}`:'';option.textContent=`${wheel.name} · ${wheel.realm} · ${wheel.mainstatKey}${owner}${ownerMatch}`;picker.append(option);}picker.value=selected??'';};
  filter.addEventListener('input',fill);picker.addEventListener('change',()=>{wheelSlot.wheelId=picker.value||null;wheelSlot.enhanceLevel=null;wheelSlot.refinementLevel=null;render();invalidate();});fill();wrap.append(heading,filterLabel,filter,pickerLabel,picker);
  const mechanics=document.createElement('p');mechanics.className='help';mechanics.setAttribute('aria-live','polite');
  if(wheelSlot.wheelId===null)mechanics.textContent='This optional Wheel slot is empty or unspecified.';
  else{const fingerprint=wheelMechanics?.wheels.find(row=>row.wheelId===wheelSlot.wheelId);if(!fingerprint)mechanics.textContent='No mechanics-track fingerprint is available for this Wheel.';else if(fingerprint.crosswalkStatus!=='UNIQUE')mechanics.textContent=`Mechanics track: ${fingerprint.crosswalkStatus.toLowerCase()} client crosswalk. Passive behavior remains unresolved.`;else mechanics.textContent=`Mechanics track fingerprint: ${fingerprint.mechanicCategories.join(', ')||'no categorized command effects'}; ${fingerprint.potentiallyLinkedStates} potentially linked state${fingerprint.potentiallyLinkedStates===1?'':'s'}. This static superset does not establish activation, magnitude, timing, legality, stacking, or optimality.`;}
  wrap.append(mechanics);
  const upgrade=document.createElement('select'),unknown=document.createElement('option');unknown.value='';unknown.textContent='Unknown enhancement';upgrade.append(unknown);
  for(let n=0;n<=15;n++){const option=document.createElement('option');option.value=String(n);option.textContent=n<=3?`E${n}`:`E3 + ${n-3}`;upgrade.append(option);}
  upgrade.value=wheelSlot.enhanceLevel??'';upgrade.disabled=wheelSlot.wheelId===null;
  const refinement=document.createElement('select'),refinementUnknown=document.createElement('option');refinementUnknown.value='';refinementUnknown.textContent='Unknown refinement';refinement.append(refinementUnknown);
  for(let n=0;n<=3;n++){const option=document.createElement('option');option.value=String(n);option.textContent=`R${n}`;refinement.append(option);}
  refinement.value=wheelSlot.refinementLevel??'';refinement.disabled=wheelSlot.wheelId===null;
  const preview=document.createElement('p');preview.className='help';preview.setAttribute('aria-live','polite');
  function updatePreview(){
    if(wheelSlot.wheelId===null){preview.textContent='Choose a Wheel and explicit enhancement to preview its catalog main stat. Refinement controls passive parameters separately.';return;}
    const boundary=clientBuild==='pc-res151-build51'?assessInstalledWheelIdentity(wheelSlot.wheelId,wheelCurrentCompatibility):null;
    if(boundary&&!boundary.catalogMainstatBaseMatches){preview.textContent=`Installed-client Wheel Item is not confirmed (${boundary.status}); no current-build main-stat contribution is assembled.`;return;}
    if(wheelSlot.enhanceLevel==null){preview.textContent='Choose explicit enhancement to preview this Wheel’s catalog main stat. Refinement controls passive parameters separately.';return;}
    try{const result=resolveWheelMainstat({catalogRevision:catalog.source.revision,wheelId:wheelSlot.wheelId,enhanceLevel:wheelSlot.enhanceLevel},catalog),owner=member.characterId!==null&&result.wheel.ownerAwakenerId===member.characterId?' Catalog owner matches the selected character.':result.wheel.ownerAwakenerName?` Catalog-associated owner: ${result.wheel.ownerAwakenerName}.`:'';const tags=result.wheel.searchTags.length?` Discovery tags: ${result.wheel.searchTags.join(', ')}.`:'',installedNote=boundary?` Installed Item main-stat base matches the pinned catalog; current enhancement scaling is unverified.${boundary.initialDirectPropertiesEqual===null?' Historical direct-property comparison is unavailable.':boundary.initialDirectPropertiesEqual?'':' Initial direct-property rules changed in this client.'}`:'';preview.textContent=`Catalog main stat: ${result.stat} +${result.value}${result.unit==='percent'?'%':''}. ${result.trace.baseValue} + ${result.trace.growthSteps} × ${result.trace.perLevel} = ${result.value}.${owner}${tags} Refinement ${wheelSlot.refinementLevel==null?'is unknown':`is R${wheelSlot.refinementLevel}`}; passive execution remains separate.${installedNote}`;}catch(error){preview.textContent=error.message;}
  }
  upgrade.addEventListener('change',()=>{wheelSlot.enhanceLevel=upgrade.value===''?null:Number(upgrade.value);updatePreview();invalidate();});refinement.addEventListener('change',()=>{wheelSlot.refinementLevel=refinement.value===''?null:Number(refinement.value);updatePreview();invalidate();});wrap.append(...labelled(`Wheel ${index+1} enhancement`,upgrade,prefix+'-enhance'),...labelled(`Wheel ${index+1} refinement`,refinement,prefix+'-refinement'),preview);updatePreview();return wrap;
}
function render(){
  $('team').replaceChildren();
  for(const [i,member] of team.entries()){
    const section=document.createElement('section'),h=document.createElement('h2');h.textContent=`Slot ${i+1}`;section.className='build-slot';section.append(h);
    section.append(...labelled('Character',select(catalog.characters,member.characterId,v=>{member.characterId=v;member.gnosticRank=null;member.advancementTalentId=null;member.advancementLevel=null;render();},'Choose character'),member.slotId+'-character'));
    const primary=document.createElement('p'),details=document.createElement('details'),summary=document.createElement('summary'),trace=document.createElement('pre');primary.className='help';primary.setAttribute('aria-live','polite');summary.textContent='Primary-stat arithmetic and evidence';details.append(summary,trace);
    function updatePrimary(){
      trace.textContent='';details.hidden=true;
      if(!clientBuild||!member.characterId||member.level==null||member.gnosticRank==null){primary.textContent='Choose client rules, character, level and Gnostic rank to calculate primary base stats.';return;}
      try{const data=selectedClientData();if(!data)throw new Error('No matching client build data is loaded.');const hasAdvancement=member.advancementTalentId!=null&&member.advancementLevel!=null;const r=hasAdvancement?resolveClientAdvancementPrimary({build:clientBuild,characterId:member.characterId,level:member.level,gnosticRank:member.gnosticRank,advancementTalentId:member.advancementTalentId,advancementLevel:member.advancementLevel},data):resolveClientBuildPrimary({build:clientBuild,characterId:member.characterId,level:member.level,gnosticRank:member.gnosticRank},data);primary.textContent=`${hasAdvancement?'Primary stats after selected advancement':'Primary base stats before advancement'}: CON ${r.stats.CON} · ATK ${r.stats.ATK} · DEF ${r.stats.DEF}. Equipment and battle effects are excluded.`;trace.textContent=JSON.stringify(r,null,2);details.hidden=false;}catch(e){primary.textContent=e.message;}
    }
    const level=document.createElement('input');level.type='number';level.min='1';level.step='1';level.value=member.level??'';level.placeholder='Unknown';level.addEventListener('input',()=>{member.level=level.value===''?null:Number(level.value);updatePrimary();invalidate();});section.append(...labelled('Character level',level,member.slotId+'-level'));
    const gnostic=document.createElement('select'),blank=document.createElement('option');blank.value='';blank.textContent='Unknown Gnostic rank';gnostic.append(blank);
    for(let n=0;n<=5;n++){const option=document.createElement('option');option.value=String(n);option.textContent=String(n);gnostic.append(option);}
    gnostic.value=member.gnosticRank??'';gnostic.addEventListener('change',()=>{member.gnosticRank=gnostic.value===''?null:Number(gnostic.value);updatePrimary();invalidate();});section.append(...labelled('Gnostic Potential rank',gnostic,member.slotId+'-gnostic'),primary,details);updatePrimary();
    const clientCharacter=selectedClientData()?.characters.find(row=>row.characterId===member.characterId),talents=clientCharacter?.advancementTalents??[];
    const talentSelect=document.createElement('select'),talentUnknown=document.createElement('option');talentUnknown.value='';talentUnknown.textContent='Unknown advancement talent';talentSelect.append(talentUnknown);
    for(const talent of talents){const option=document.createElement('option');option.value=String(talent.clientTalentId);option.textContent=`Talent ${talent.clientTalentId} · ${talent.season}`;talentSelect.append(option);}
    talentSelect.value=member.advancementTalentId??'';talentSelect.addEventListener('change',()=>{member.advancementTalentId=talentSelect.value===''?null:Number(talentSelect.value);member.advancementLevel=null;render();invalidate();});section.append(...labelled('Season / Soulforge advancement talent',talentSelect,member.slotId+'-advancement-talent'));
    const selectedTalent=talents.find(row=>row.clientTalentId===member.advancementTalentId),advancementLevel=document.createElement('select'),levelUnknown=document.createElement('option');levelUnknown.value='';levelUnknown.textContent='Unknown advancement level';advancementLevel.append(levelUnknown);
    if(selectedTalent)for(let n=0;n<=selectedTalent.maximumLevel;n++){const option=document.createElement('option');option.value=String(n);option.textContent=String(n);advancementLevel.append(option);}
    advancementLevel.value=member.advancementLevel??'';advancementLevel.disabled=!selectedTalent;advancementLevel.addEventListener('change',()=>{member.advancementLevel=advancementLevel.value===''?null:Number(advancementLevel.value);updatePrimary();invalidate();});section.append(...labelled('Advancement level',advancementLevel,member.slotId+'-advancement-level'));
    for(const [wheelIndex,wheelSlot] of member.wheelSlots.entries())section.append(renderWheelSlot(member,wheelSlot,wheelIndex));
    const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Remove slot';remove.addEventListener('click',()=>{team=team.filter(m=>m!==member);render();invalidate();});section.append(remove);$('team').append(section);
  }
}
function current(){return {schemaVersion:2,kind:'morimens-build-plan',catalogRevision:catalog.source.revision,...(clientBuild===undefined?{}:{clientBuild}),team};}
function emptyWheelSlots(){return [{slotId:'wheel-1',wheelId:null,enhanceLevel:null,refinementLevel:null},{slotId:'wheel-2',wheelId:null,enhanceLevel:null,refinementLevel:null}];}
function uiMember(member,schemaVersion){if(schemaVersion===2){const copy=JSON.parse(JSON.stringify(member)),used=new Set(copy.wheelSlots.map(slot=>slot.slotId));for(let n=1;copy.wheelSlots.length<2;n++)if(!used.has('wheel-'+n)){copy.wheelSlots.push({slotId:'wheel-'+n,wheelId:null,enhanceLevel:null,refinementLevel:null});used.add('wheel-'+n);}return copy;}const {wheelId,wheelEnhanceLevel,...rest}=member;return {...JSON.parse(JSON.stringify(rest)),wheelSlots:[{slotId:'wheel-1',wheelId,enhanceLevel:wheelEnhanceLevel??null,refinementLevel:null},{slotId:'wheel-2',wheelId:null,enhanceLevel:null,refinementLevel:null}]};}
$('client-build').addEventListener('change',()=>{clientBuild=$('client-build').value||null;if(catalog){render();invalidate();}});
$('add').addEventListener('click',()=>{while(team.some(m=>m.slotId==='slot-'+nextId))nextId++;team.push({slotId:'slot-'+nextId++,characterId:null,level:null,gnosticRank:null,advancementTalentId:null,advancementLevel:null,wheelSlots:emptyWheelSlots()});render();invalidate();});
$('save').addEventListener('click',()=>{try{const r=validateBuildPlan(current(),catalog);$('plan').value=JSON.stringify(r.plan,null,2);$('plan-status').textContent='Plan exported. Primary base stats and Wheel main stats have separate previews; final battle stats and sequence damage remain unresolved.';$('error').textContent='';}catch(e){$('error').textContent=e.message;}});
$('assemble').addEventListener('click',()=>{try{const data=selectedClientData()??clientDataByBuild['pc-res144-build51'];const r=assembleKnownBuildComponents(current(),catalog,data,wheelCurrentCompatibility);$('assembly').textContent=JSON.stringify(r,null,2);$('assembly-status').textContent=r.assemblyStatus==='KNOWN_COMPONENTS_RESOLVED'?'Known character and Wheel components resolved. This is still not a complete battle-property snapshot.':`${r.issues.length} build input or source-compatibility issue${r.issues.length===1?' remains':'s remain'}.`;$('error').textContent='';}catch(e){$('error').textContent=e.message;}});
$('load').addEventListener('click',()=>{try{const r=validateBuildPlan(JSON.parse($('plan').value),catalog);team=r.plan.team.map(member=>uiMember(member,r.plan.schemaVersion));clientBuild=r.plan.clientBuild;$('client-build').value=clientBuild??'';render();$('plan-status').textContent=r.plan.schemaVersion===1?'Legacy plan loaded into the two-Wheel editor; refinement remains unknown until selected.':'Plan loaded. No combat assumptions were filled in.';$('error').textContent='';}catch(e){$('error').textContent=e.message;}});
try{const responses=await Promise.all([fetch('build-catalog.json'),fetch('client-build-data.json'),fetch('client-build-data-res150.json'),fetch('client-build-data-res151.json'),fetch('wheel-mechanics-capability-catalog.json'),fetch('wheel-current-compatibility.json')]);if(responses.some(r=>!r.ok))throw new Error('Could not load build data');const [loadedCatalog,historical,previous,installed,loadedWheelMechanics,loadedWheelCurrentCompatibility]=await Promise.all(responses.map(r=>r.json()));catalog=loadedCatalog;wheelMechanics=loadedWheelMechanics;wheelCurrentCompatibility=loadedWheelCurrentCompatibility;clientDataByBuild={[historical.build]:historical,[previous.build]:previous,[installed.build]:installed};for(const id of ['add','save','load','assemble'])$(id).disabled=false;$('add').click();}catch(e){$('error').textContent=e.message;}
